-- Post-migration, pre-deploy integrity gate for migration 282.
-- Every SELECT must return zero rows after apply.

SELECT 'battles.is_demo_data' AS invalid_column FROM (SELECT 1) WHERE NOT EXISTS (SELECT 1 FROM pragma_table_info('battles') WHERE name='is_demo_data' AND type='INTEGER' AND "notnull"=1 AND dflt_value='0') UNION ALL SELECT 'battles.expires_at' FROM (SELECT 1) WHERE NOT EXISTS (SELECT 1 FROM pragma_table_info('battles') WHERE name='expires_at' AND type='TEXT' AND "notnull"=0 AND dflt_value IS NULL) UNION ALL SELECT 'battle_answers.is_demo_data' FROM (SELECT 1) WHERE NOT EXISTS (SELECT 1 FROM pragma_table_info('battle_answers') WHERE name='is_demo_data' AND type='INTEGER' AND "notnull"=1 AND dflt_value='0') UNION ALL SELECT 'battle_answers.expires_at' FROM (SELECT 1) WHERE NOT EXISTS (SELECT 1 FROM pragma_table_info('battle_answers') WHERE name='expires_at' AND type='TEXT' AND "notnull"=0 AND dflt_value IS NULL);

SELECT 'battles:' || id AS invalid_demo_row FROM battles WHERE is_demo_data NOT IN (0,1) OR is_demo_data IS NULL OR (is_demo_data=1 AND expires_at IS NULL) UNION ALL SELECT 'battle_answers:' || id FROM battle_answers WHERE is_demo_data NOT IN (0,1) OR is_demo_data IS NULL OR (is_demo_data=1 AND expires_at IS NULL);

SELECT 'idx_battles_demo' AS invalid_index FROM (SELECT 1) WHERE NOT EXISTS (SELECT 1 FROM pragma_index_list('battles') WHERE name='idx_battles_demo' AND "unique"=0) OR NOT EXISTS (SELECT 1 FROM pragma_index_info('idx_battles_demo') WHERE seqno=0 AND name='is_demo_data') OR NOT EXISTS (SELECT 1 FROM pragma_index_info('idx_battles_demo') WHERE seqno=1 AND name='expires_at') OR (SELECT COUNT(*) FROM pragma_index_info('idx_battles_demo'))<>2 UNION ALL SELECT 'idx_battle_answers_demo' FROM (SELECT 1) WHERE NOT EXISTS (SELECT 1 FROM pragma_index_list('battle_answers') WHERE name='idx_battle_answers_demo' AND "unique"=0) OR NOT EXISTS (SELECT 1 FROM pragma_index_info('idx_battle_answers_demo') WHERE seqno=0 AND name='is_demo_data') OR NOT EXISTS (SELECT 1 FROM pragma_index_info('idx_battle_answers_demo') WHERE seqno=1 AND name='expires_at') OR (SELECT COUNT(*) FROM pragma_index_info('idx_battle_answers_demo'))<>2;

SELECT * FROM pragma_foreign_key_check;
